 search:['Selected products',`<button class="option-alt" data-action="product" data-id="${S.order.necklace||'necklace'}">${esc(products[S.order.necklace||'necklace'].name)} ›</button><button class="option-alt" data-action="product" data-id="${S.order.mug}">${esc(products[S.order.mug].name)} ›</button><p class="fine">Search is limited to the two selected products in this demo.</p>`],
 'price-drop':['Price drop','<p>There are no verified new price drops for these selected items. Compare complete-order alternatives at checkout.</p>'],
