function reset(){tourPlaying=false;clearTimeout(tourTimer);stopVoice(true);S.page='cart';S.order={...initial};S.conditions={...defaults};S.origins={};S.options=[];S.text='';S.source='Current order';S.modelNote='';S.undo=null;S.updated=false;S.overlay=null;S.history=[];S.pendingExtra=0;S.unavailable=[];S.failure='none';S.context='cart';$('#context').value='cart';$('#context-note').innerHTML='';overlayScroll.clear();$('#failure').value='none';$('#tour-label').textContent='';render();}
