function aiStatus(text){$('#ai-status').textContent=text;const el=$('#modal-ai-status');if(el)el.textContent=text;}
async function loadAI(){
 if(aiReady)return true;if(aiLoading)return false;
  aiLoading=true;aiError='';$('#load-ai').disabled=true;if(S.overlay?.type==='ai-needed')renderOverlay();aiStatus('Loading local Qwen model…');
 return new Promise(resolve=>{
  aiWorker=new Worker('./ai-worker.js',{type:'module'});
  const timer=setTimeout(()=>{aiLoading=false;aiError='Model download timed out. Check your connection and retry.';aiStatus(aiError);aiWorker?.terminate();$('#load-ai').disabled=false;resolve(false);if(S.overlay?.type==='ai-needed')renderOverlay();},180000);
  aiWorker.onmessage=({data:d})=>{
   if(d.type==='progress')aiStatus(d.text);
   if(d.type==='ready'){clearTimeout(timer);aiReady=true;aiLoading=false;$('#load-ai').textContent='Local model ready';aiStatus('Ready · Qwen2.5 0.5B · '+d.backend+'');resolve(true);if(S.overlay?.type==='ai-needed')renderOverlay();}
   if(d.type==='result'||d.type==='error'&&d.id){if(inferencePending&&inferencePending.id===d.id){const pending=inferencePending;inferencePending=null;clearTimeout(pending.timer);d.type==='result'?pending.resolve(d.value):pending.reject(Error(d.message));}}
   else if(d.type==='error'){clearTimeout(timer);aiLoading=false;aiError='Model could not load. You can retry or edit conditions manually.';aiStatus(aiError);$('#load-ai').disabled=false;aiWorker?.terminate();resolve(false);if(S.overlay?.type==='ai-needed')renderOverlay();}
  };
  aiWorker.onerror=()=>{clearTimeout(timer);aiLoading=false;aiError='Could not download the model runtime. Try a compatible browser or manual conditions.';aiStatus(aiError);$('#load-ai').disabled=false;resolve(false);if(S.overlay?.type==='ai-needed')renderOverlay();};
  aiWorker.postMessage({type:'load'});
 });
}
async function interpret(text){
 if(inferencePending){toast('The model is still finishing your previous request. Please wait.');return;}
 text=text.trim();if(!text){toast('Tell us what you would like to keep or change.');return;}
 if(text.length>500){toast('Please keep your request under 500 characters.');return;}
 S.text=text;S.history=[];
 if(!aiReady){open('ai-needed');return;}
 const myID=++requestID;open('busy');
 try{
  const value=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{inferencePending=null;reject(Error('The model took too long. Your request is saved.'));aiWorker?.terminate();aiReady=false;$('#load-ai').disabled=false;$('#load-ai').textContent='Reload local model';},90000);inferencePending={id:myID,resolve,reject,timer};aiWorker.postMessage({type:'infer',id:myID,text,previous:S.conditions});});
  if(S.overlay?.type!=='busy')return;
  if(value.unsupported){open('failure',{title:'Let’s keep this to your order',message:'This demo can replace one item, protect either selected item, preserve mug features, and set a total budget. It cannot add items or promise a delivery date.',retry:false});return;}
  const checked=mergeRequest(S.conditions,value,S.text);S.conditions=checked.conditions;checked.changed.forEach(k=>S.origins[k]='Interpreted from your request · check below');S.modelNote=checked.clarification?checked.question:checked.needsReview?'An item was marked as protected without a clear request. Please check the interpretation below.':checked.changed.length?'Updated: '+checked.changed.map(k=>({budget:'budget',floral:'floral decoration',keepMug:'original mug',keepNecklace:'original necklace',lid:'lid',freeShipping:'shipping requirement',cheapest:'ranking',ignoreHistory:'history preference'}[k])).join(', ')+'. Other requirements were preserved.':'Previous requirements preserved. Please check below.';S.source='AI interpretation · explicit-topic guard · pending confirmation';open('conditions');
 }catch(e){if(S.overlay?.type==='busy'){aiError=e.message;open('ai-needed');}}
}
function updateOrder(extra=0){
 const o=S.options[S.chosen];if(!o)return;
 if(S.overlay?.updating)return;
 if(S.failure==='price'&&!extra){S.failure='none';$('#failure').value='none';open('quote-change');return;}
 if(S.failure==='stock'){S.unavailable.push(o.product.id);S.failure='none';$('#failure').value='none';open('failure',{title:'This alternative is no longer available',message:'Availability changed before confirmation. This offer is now excluded from further results. Nothing was replaced.',retry:false});return;}
 if(S.failure==='timeout'){S.failure='none';$('#failure').value='none';open('failure',{title:'The quote service did not respond',message:'We could not recheck the total. Retry the review or return to checkout.',retry:true});return;}
 if(S.conditions.budget&&o.quote.total+extra>=S.conditions.budget*100){toast('The revised quote is outside your budget.');return;}
 try{const old={...S.order};S.order={...commit(S.order,o,S.reviewVersion),extra};S.undo=old;S.undoVersion=S.order.version;S.updated=o.changed;closeAll();S.preserveScroll=true;render();$('.screen .scroll').scrollTop=0;toast(o.changed?'Order updated. You can undo this change.':'Order confirmed. No items changed.');}catch{open('failure',{title:'Your order changed',message:'Refresh the options so we don’t overwrite a newer edit.',retry:false});}
}
