app.addEventListener('input',e=>{if(e.target.id==='request-input')S.text=e.target.value;if(e.target.id==='voice-text')syncVoiceControls();});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(actions[a])actions[a](b.dataset.id);else open(a,{id:b.dataset.id},!!S.overlay);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&S.overlay)close();if(e.key==='Tab'&&S.overlay){const els=[...$('.overlay').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&(document.activeElement===first||!$('.overlay').contains(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!$('.overlay').contains(document.activeElement))){e.preventDefault();first.focus();}}});
$('#restart').onclick=reset;
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));
$('#load-ai').onclick=loadAI;
$('#context').onchange=e=>{S.context=e.target.value;$('#context-note').innerHTML=`<p class="note">${S.context==='cart'?'No behavior signals used.':S.context==='session'?'Fixture: compared three floral mugs in this session.':'Fixture: repeatedly saved and revisited this original decorative cup. Prefer keeping it, without locking it.'}</p>`;if(S.overlay?.type==='options')generate();};
$('#failure').onchange=e=>S.failure=e.target.value;
$('#tour').onclick=()=>{reset();tourPlaying=true;const steps=[{delay:0,caption:'01 / Two selected products. No open-ended shopping.',run:()=>{}},{delay:4500,caption:'02 / Checkout reveals the complete cost.',run:()=>navigate('checkout')},{delay:9500,caption:'03 / Open the adjustment where the cost becomes clear.',run:()=>{$('.screen .scroll').scrollTo({top:9999,behavior:'smooth'});}},{delay:14000,caption:'04 / Preview a change without altering the order.',run:beginOptions},{delay:20000,caption:'05 / Compare the exact change and all fees.',run:()=>actions.review()},{delay:26000,caption:'06 / Confirm once. The original order can be restored.',run:()=>actions.update()},{delay:32000,caption:'07 / A stricter floral requirement can produce no match.',run:()=>{applyPreset('flowers');}},{delay:39000,caption:'08 / Preserve the requirements. Let the user decide what changes.',run:()=>generate()},{delay:46000,caption:'Walkthrough complete. Try your own request or reset.',run:()=>{tourPlaying=false;}}];let i=0;function next(){steps[i].run();$('#tour-label').textContent=steps[i].caption;if(i<steps.length-1){const wait=steps[i+1].delay-steps[i].delay;i++;tourTimer=setTimeout(next,wait);}}next();};
document.addEventListener('pointerdown',e=>{if(tourPlaying&&!e.target.closest('#tour')){tourPlaying=false;clearTimeout(tourTimer);$('#tour-label').textContent='Walkthrough paused. Continue at your own pace.';}});
window.addEventListener('pagehide',()=>{stopVoice(true);if(voiceURL)URL.revokeObjectURL(voiceURL);});
render();
